-- Migration batch 1 (docs/DECISIONS.md D-019, D-020, D-021).
--   1. signup_intents: signup details wait here (service role only) until the email code is verified.
--   2. products.external_url plus the publish rule "a file or an external link".
--   3. profiles.phone becomes editable by its owner.
-- Do not edit this file once pushed.

-- ---------------------------------------------------------------------------
-- 1. signup_intents
-- ---------------------------------------------------------------------------
-- One row per email (a new signup replaces the old one). Bound to the browser that started
-- signup: token_hash is the SHA-256 (hex) of a random token kept in an httpOnly cookie.
-- ip_hash is an HMAC of the client IP (never the raw IP), used only for rate limiting.

create table public.signup_intents (
  id uuid primary key default gen_random_uuid(),
  email text not null unique check (email = lower(email) and char_length(email) between 3 and 254),
  username text not null check (username ~ '^[a-z0-9-]{3,30}$'),
  full_name text not null check (char_length(full_name) between 1 and 80),
  phone text check (phone is null or phone ~ '^\+[1-9][0-9]{6,14}$'),
  token_hash text not null check (token_hash ~ '^[0-9a-f]{64}$'),
  attempts integer not null default 1 check (attempts >= 1),
  window_started_at timestamptz not null default now(),
  ip_hash text check (ip_hash is null or ip_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '30 minutes')
);

create index signup_intents_expires_at_idx on public.signup_intents (expires_at);
create index signup_intents_ip_hash_idx on public.signup_intents (ip_hash, created_at);

alter table public.signup_intents enable row level security;
revoke all on table public.signup_intents from anon, authenticated;

comment on table public.signup_intents is
  'Service role only. RLS enabled with no policies and no client grants on purpose. Rows expire after 30 minutes.';

-- ---------------------------------------------------------------------------
-- 2. products.external_url and the publish rule
-- ---------------------------------------------------------------------------
-- The link is delivered only after a verified payment, like a file, so it is NOT added to the
-- public_products view (that view lists its columns explicitly).

alter table public.products
  add column external_url text,
  add constraint products_external_url_https check (
    external_url is null or (external_url ~ '^https://[^[:space:]]+$' and char_length(external_url) <= 2048)
  );

-- A digital product can only be published with at least one file or an external link.
-- Known gap (D-021): deleting the last file of an already published product is not blocked here;
-- the app guards that.
create or replace function public.enforce_product_deliverable()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'published'
     and new.type = 'digital'
     and new.external_url is null
     and not exists (select 1 from public.product_files f where f.product_id = new.id) then
    raise exception 'A digital product needs a file or an external link before it can be published.'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger products_require_deliverable
  before insert or update of status, type, external_url on public.products
  for each row execute function public.enforce_product_deliverable();

revoke all on function public.enforce_product_deliverable() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. profiles.phone: the owner may update it (format still enforced by profiles_phone_format)
-- ---------------------------------------------------------------------------
-- Needed so signup can save the phone with the user's own session (RLS "profiles: update own").

grant update (phone) on public.profiles to authenticated;
